#!/usr/bin/env python3
# deck-patch-v7.py — embed Mission Control v7 into Serve Deck (R4es7I5lGGySML1I)
import json,base64,urllib.request,hashlib
JWT="__JWT__"
WID="R4es7I5lGGySML1I"
API="http://localhost:5678/api/v1/workflows/"+WID
HTML=base64.b64decode("").decode("utf-8")
print("html bytes:",len(HTML),"md5:",hashlib.md5(HTML.encode()).hexdigest())
req=urllib.request.Request(API,headers={"X-N8N-API-KEY":JWT})
wf=json.loads(urllib.request.urlopen(req).read())
hit=False
for n in wf["nodes"]:
    if n["name"]=="Serve Deck":
        n["parameters"]["responseBody"]=HTML
        hit=True
assert hit,"Serve Deck node not found"
payload=json.dumps({"name":wf["name"],"nodes":wf["nodes"],"connections":wf["connections"],"settings":wf.get("settings",{})}).encode()
req2=urllib.request.Request(API,data=payload,method="PUT",headers={"X-N8N-API-KEY":JWT,"Content-Type":"application/json"})
r=json.loads(urllib.request.urlopen(req2).read())
print("updated:",r.get("id"),"updatedAt:",r.get("updatedAt"))
PY